/**
 * Structured-event hook for facilitator observability. The three entry points
 * (`verifyX402Payment`, `settleX402Payment`, `verifySelfAttestation`) accept an
 * optional `events` sink and emit exactly one event per call, at the existing
 * return/throw points. Default is a no-op — wiring metrics or logging is the
 * caller's choice.
 */
export type FacilitatorEventType = 'verify' | 'settle' | 'self_verify';
export type FacilitatorEvent = {
    type: FacilitatorEventType;
    /** 'ok' on success, otherwise the failure reason (e.g. 'scheme_mismatch'). */
    outcome: string;
    network?: string;
    asset?: string;
    /** Atomic units of `asset`, as a decimal string. */
    amount?: string;
    payer?: string;
    transaction?: string;
    endpoint?: string;
    latencyMs: number;
    /** Extra detail (e.g. an error message) when the outcome alone is not enough. */
    reason?: string;
    /**
     * Caller-supplied id tying every event of one request together — the
     * `self_verify`, the `verify` and the `settle` of a single paid call, and
     * whatever the surrounding server logs under the same id.
     *
     * Opaque and never generated here. A facilitator that minted its own would
     * produce a different id per entry point and correlate nothing; the id has
     * to come from whoever owns the request boundary. `examples/demo-server-gce.mjs`
     * already does this for its own logs — this field is what lets the rest of
     * the stack join against those.
     */
    correlationId?: string;
};
export interface FacilitatorEvents {
    /**
     * MUST NOT throw or reject. A sink is observability; it does not get a vote
     * on whether a payment succeeded. `safeEmit` enforces that regardless, but
     * a failing sink is a bug in the sink.
     *
     * Async sinks are allowed — most real ones are — which is precisely why the
     * return type is declared: an `async` emit that rejects produces a promise
     * nobody was awaiting, and Node terminates the process on an unhandled
     * rejection by default.
     */
    emit(event: FacilitatorEvent): void | Promise<void>;
}
/**
 * Emit without letting the sink change the outcome.
 *
 * A metrics backend that throws — a full buffer, a closed socket, a typo in a
 * label — must not turn a settled payment into a reported failure. That is
 * not hypothetical bookkeeping: settleX402Payment emitted its success event
 * INSIDE the try that wraps the broadcast, so a throwing sink was caught by
 * the settlement catch, re-emitted as an `error` event, and re-thrown to the
 * caller after the funds had already moved. If the second emit threw too, the
 * original outcome vanished entirely.
 *
 * Sink errors are swallowed rather than logged: this is a library, and a sink
 * that fails on every call would otherwise turn one broken dependency into
 * unbounded noise on someone else's stderr.
 */
export declare function safeEmit(events: FacilitatorEvents | undefined, event: FacilitatorEvent): void;
/** Default sink: discards everything. */
export declare const noopFacilitatorEvents: FacilitatorEvents;
/**
 * Trivial in-memory FacilitatorEvents implementation: counts events by
 * `type:outcome` and remembers the last event timestamp per type. Useful for
 * tests and for embedding a `/metrics`-style endpoint without a dependency.
 */
export declare class InMemoryMetrics implements FacilitatorEvents {
    private readonly counts;
    private readonly lastEventAt;
    emit(event: FacilitatorEvent): void;
    /** Events seen for a type, or for one specific type+outcome pair. */
    count(type: FacilitatorEventType, outcome?: string): number;
    /** ISO-8601 timestamp of the most recent event of this type, if any. */
    lastEvent(type: FacilitatorEventType): string | undefined;
    /** Flat `{ "verify:ok": 3, ... }` view of all counters. */
    snapshot(): Record<string, number>;
}
